import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Filter to significant features based on t-test
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if abs(stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i]).statistic) > 2.0:
            sig_features.append(fid)

    # Remove near-duplicates
    keep = set()
    corr_pairs = [
        ('TOF14B', 'HII18'), ('IRE15B', 'PRX1'), ('DZLO16', 'ANK11B'),
        ('MGA13B', 'NVV13B'), ('RWA8B', 'PRX1'), ('SXO17', 'KSQH15'),
        ('VKO13B', 'PRX1'), ('ANK11B', 'NVV13B'), ('MGA13B', 'ANK11B'),
        ('DWZT15', 'ANK11B'), ('DZLO16', 'NVV13B'), ('DWZT15', 'NVV13B'),
        ('PRX1', 'FMQI13L'), ('RWA8B', 'IRE15B'), ('MGA13B', 'DWZT15'),
        ('TOF14B', 'SXO17'), ('TOF14B', 'KSQH15'), ('ZQYC5', 'PRX1'),
        ('TYSW1', 'PRX1'), ('DZLO16', 'OGO8')
    ]

    for fid in sig_features:
        # Check if this feature is part of any correlated pair
        is_correlated = False
        for pair in corr_pairs:
            if fid in pair:
                is_correlated = True
                # Only add one feature from each pair
                if pair[0] not in keep and pair[1] not in keep:
                    # Add the one with higher effect size
                    effect0 = np.mean(feats.x[feats.y==1, feats.column(pair[0])]) - np.mean(feats.x[feats.y==0, feats.column(pair[0])])
                    effect1 = np.mean(feats.x[feats.y==1, feats.column(pair[1])]) - np.mean(feats.x[feats.y==0, feats.column(pair[1])])
                    if abs(effect0) >= abs(effect1):
                        keep.add(pair[0])
                    else:
                        keep.add(pair[1])
                break

        # If not correlated, add it
        if not is_correlated:
            keep.add(fid)

    # Select top features by effect size
    drivers = []
    scores = []
    for i, fid in enumerate(feats.ids):
        if fid in keep:
            effect = np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])
            scores.append((abs(effect), fid))

    scores.sort(reverse=True)
    drivers = [fid for _, fid in scores[:MAX_DRIVERS]]

    # Build columns and products
    columns = drivers[:]
    products = []

    # Add interaction terms for top features
    for i in range(len(drivers)):
        for j in range(i+1, len(drivers)):
            if drivers[i] != drivers[j]:
                products.append((drivers[i], drivers[j]))

    # Weighted score using top features
    loadings = {}
    for i, fid in enumerate(feats.ids):
        if fid in drivers:
            effect = np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i])
            loadings[fid] = effect

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

